import zeros = require( '@stdlib/ndarray/zeros' );
import offsets = require( './index' );


// TESTS //

// The function returns an array...
{
	offsets( [ zeros( [ 1 ] ) ] ); // $ExpectType number[]
}

// The compiler throws an error if the function is not provided an array-like object containing ndarrays...
{
	offsets( '5' ); // $ExpectError
	offsets( 5 ); // $ExpectError
	offsets( true ); // $ExpectError
	offsets( false ); // $ExpectError
	offsets( null ); // $ExpectError
	offsets( {} ); // $ExpectError
	offsets( [ '5' ] ); // $ExpectError
	offsets( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	offsets(); // $ExpectError
	offsets( [ zeros( [ 1 ] ) ], {} ); // $ExpectError
}
